// ═══════════════════════════════════════════════════
// CHUNKER & METADATA ENRICHER NODE
// Splits text into semantic chunks for ChromaDB RAG
// ═══════════════════════════════════════════════════
const parsed = $input.first().json.data || $input.first().json;
const text = parsed.extracted_text || '';
const filename = parsed.filename || 'unknown_document';
const metrics = parsed.extracted_metrics || {};

const CHUNK_SIZE = 800; // characters
const CHUNK_OVERLAP = 100;
const chunks = [];

if (text.length > 0) {
  let start = 0;
  let chunkIdx = 0;
  while (start < text.length) {
    const end = Math.min(start + CHUNK_SIZE, text.length);
    const chunkText = text.substring(start, end).trim();
    if (chunkText.length > 50) {
      chunks.push({
        chunk_index: chunkIdx,
        chunk_text: chunkText,
        filename: filename,
        total_characters: chunkText.length,
        crops_referenced: metrics.komoditas_disebut || [],
        ai_summary: parsed.ai_summary || ''
      });
      chunkIdx++;
    }
    start += (CHUNK_SIZE - CHUNK_OVERLAP);
  }
}

return [{
  json: {
    document_title: filename,
    source_type: parsed.file_type || 'pdf',
    total_chunks: chunks.length,
    total_characters: text.length,
    chunks: chunks,
    ai_summary: parsed.ai_summary || '',
    extracted_metrics: metrics,
    timestamp: new Date().toISOString()
  }
}];

